import express from 'express';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import jwt from 'jsonwebtoken';
import crypto from 'node:crypto';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {mountBox} from './box.js';
import {promisify} from 'node:util';

const publicDir=path.join(path.dirname(fileURLToPath(import.meta.url)),'public');
const equal=(a,b)=>crypto.timingSafeEqual(crypto.createHash('sha256').update(String(a||'')).digest(),crypto.createHash('sha256').update(String(b||'')).digest());
export function createApp({db,adminUser,adminPassword,secret,commerce,provider}) {
  if(!db||!adminUser||typeof adminPassword!=='string'||adminPassword.length<12||typeof secret!=='string'||secret.length<32) throw Error('Configure as credenciais exclusivas do BOX.');
  const app=express();app.disable('x-powered-by');app.set('trust proxy',1);
  app.use(helmet({contentSecurityPolicy:false}));
  app.use('/api/admin/box/catalog',express.json({limit:'4mb'}));
  app.use(express.json({limit:'32kb'}));
  app.use('/api/',(req,res,next)=>{res.setHeader('Cache-Control','no-store');next()});
  app.use('/api/',rateLimit({windowMs:60000,limit:120,standardHeaders:'draft-8',legacyHeaders:false}));
  const loginLimiter=rateLimit({windowMs:60000,limit:5,standardHeaders:'draft-8',legacyHeaders:false,message:{error:'Muitas tentativas. Aguarde um minuto.'}});
  const activationLimiter=rateLimit({windowMs:60000,limit:10,standardHeaders:'draft-8',legacyHeaders:false,message:{error:'Muitas tentativas de ativação. Aguarde um minuto.'}});
  function adminAuth(req,res,next){
    try {
      const token=String(req.headers.authorization||'').replace(/^Bearer\s+/i,'');
      const payload=jwt.verify(token,secret,{algorithms:['HS256'],audience:'rbx-box-admin',issuer:'rbx-box-server'});
      if(payload.type!=='box_admin'||payload.sub!==adminUser)throw Error('Token inválido');
      req.admin=payload;next();
    }catch{res.status(401).json({error:'Entre no painel administrativo do BOX.'});}
  }
  app.post('/api/admin/login',loginLimiter,(req,res)=>{
    const username=String(req.body?.username||'');const password=String(req.body?.password||'');
    const userOk=equal(username,adminUser),passwordOk=equal(password,adminPassword);
    if(!userOk||!passwordOk)return res.status(401).json({error:'Usuário ou senha inválidos.'});
    res.json({token:jwt.sign({type:'box_admin'},secret,{subject:adminUser,audience:'rbx-box-admin',issuer:'rbx-box-server',algorithm:'HS256',expiresIn:'8h'})});
  });
  mountBox(app,{db,adminAuth,secret,limiter:activationLimiter});
  if(commerce)mountMembers(app,{db,adminAuth,secret,config:commerce,provider});
  app.get('/health',async(_req,res)=>{try{await db.query('SELECT 1');res.json({ok:true,service:'rbx-box-server'});}catch{res.status(503).json({ok:false,service:'rbx-box-server'});}});
  app.get('/',(_req,res)=>res.redirect('/membros.html'));
  app.get('/membros.html',(_req,res)=>res.type('html').send(BOX_PAGES["membros.html"]));
  app.get('/compras.html',(_req,res)=>res.type('html').send(BOX_PAGES["compras.html"]));
  app.get('/box.html',(_req,res)=>res.type('html').send(BOX_PAGES["box.html"]));
  app.use(express.static(publicDir));
  app.use('/api/',(_req,res)=>res.status(404).json({error:'Rota não encontrada no servidor BOX.'}));
  app.use((err,req,res,next)=>{console.error('RBX BOX:',err.message);res.status(err.status||500).json({error:err.status===413?'Envio muito grande.':'Não foi possível concluir a solicitação.'});});
  return app;
}



const scrypt=promisify(crypto.scrypt),PRICE=4990,COOKIE='rbx_box_member';
const fail=(status,message)=>Object.assign(new Error(message),{status});
const route=fn=>(req,res,next)=>Promise.resolve(fn(req,res,next)).catch(next);
const hash=s=>crypto.createHash('sha256').update(s).digest('hex');
const uuid=s=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);
const validPassword=s=>typeof s==='string'&&s.length>=10&&s.length<=128;
export async function passwordHash(value){const salt=crypto.randomBytes(16).toString('hex');return salt+':'+(await scrypt(value,salt,64)).toString('hex')}
async function passwordMatches(value,stored){const [salt,expected]=stored.split(':');const actual=await scrypt(value,salt,64);return crypto.timingSafeEqual(actual,Buffer.from(expected,'hex'))}
export async function initMembers(db){
 await db.query(`CREATE TABLE IF NOT EXISTS box_members(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password_hash TEXT NOT NULL,session_version INTEGER NOT NULL DEFAULT 0,blocked BOOLEAN NOT NULL DEFAULT FALSE,recovery_hash TEXT,recovery_expires TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await db.query(`CREATE TABLE IF NOT EXISTS box_orders(id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES box_members(id),attempt TEXT NOT NULL,amount_cents INTEGER NOT NULL,source TEXT NOT NULL DEFAULT 'pix',status TEXT NOT NULL DEFAULT 'pending',payment_id TEXT UNIQUE,qr_code TEXT,qr_image TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),checked_at TIMESTAMPTZ,approved_by TEXT,UNIQUE(member_id,attempt))`);
 await db.query(`CREATE TABLE IF NOT EXISTS box_member_licenses(order_id TEXT PRIMARY KEY REFERENCES box_orders(id),member_id TEXT NOT NULL REFERENCES box_members(id),key_id BIGINT UNIQUE NOT NULL REFERENCES box_keys(id),key_cipher TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
}
export function paymentProvider({token,fetchImpl=fetch,notificationUrl}){
 async function request(path,options={}){
  if(!token)throw fail(503,'O Pix da BOX ainda está sendo configurado.');
  let response;try{response=await fetchImpl('https://api.mercadopago.com/v1/payments'+path,{...options,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(20000)})}catch{throw fail(503,'Não foi possível consultar o Pix. Tente novamente; seu pedido foi preservado.')}
  let data;try{data=await response.json()}catch{throw fail(503,'Resposta de pagamento indisponível. Tente novamente.')}
  if(!response.ok)throw fail(502,'O provedor não concluiu a solicitação do Pix. Tente novamente ou fale com o suporte.');return data;
 }
 return{create:({order,member})=>request('',{method:'POST',headers:{'X-Idempotency-Key':order.id},body:JSON.stringify({transaction_amount:PRICE/100,description:'RBX BOX — pré-venda',payment_method_id:'pix',...(notificationUrl?{notification_url:notificationUrl}:{}),external_reference:order.id,metadata:{product:'rbx-box',member_id:member.id},payer:{email:member.email,first_name:member.name}})}),get:id=>request('/'+encodeURIComponent(id))};
}
export function validatePayment(payment,order){
 if(payment.live_mode!==true)throw fail(409,'Este pagamento não é uma compra real em produção. Fale com o suporte.');
 if(String(payment.id)!==String(order.payment_id)||payment.external_reference!==order.id||payment.currency_id!=='BRL'||Math.round(Number(payment.transaction_amount)*100)!==Number(order.amount_cents)||payment.metadata?.product!=='rbx-box'||payment.metadata?.member_id!==order.member_id)throw fail(409,'O pagamento não corresponde a esta compra da BOX. Fale com o suporte.');
 return String(payment.status||'pending');
}
export function mountMembers(app,{db,adminAuth,secret,config={},provider}){
 const keySecret=config.keySecret;const encryptionKey=typeof keySecret==='string'&&keySecret.length>=32?crypto.createHash('sha256').update(keySecret).digest():null;
 const sessionSecret=crypto.createHmac('sha256',secret).update('rbx-box-member-session-v1').digest('hex');
 const payments=provider||paymentProvider({token:config.mpToken,notificationUrl:config.webhookSecret?'https://rbx-box-server.onrender.com/api/members/payment-webhook':undefined});
 const authLimit=rateLimit({windowMs:15*60000,limit:20,standardHeaders:'draft-8',legacyHeaders:false,message:{error:'Muitas tentativas. Aguarde alguns minutos.'}});
 const purchaseLimit=rateLimit({windowMs:60000,limit:12,standardHeaders:'draft-8',legacyHeaders:false,message:{error:'Aguarde um minuto antes de tentar novamente.'}});
 const statusLimit=rateLimit({windowMs:60000,limit:40,standardHeaders:'draft-8',legacyHeaders:false});
 const cleanMember=m=>({id:m.id,email:m.email,name:m.name});
 const secureCookie=config.secureCookies!==false;
 const cookieOptions={httpOnly:true,secure:secureCookie,sameSite:'strict',path:'/api/members',maxAge:7*86400000};
 function login(res,m){res.cookie(COOKIE,jwt.sign({type:'box_member',ver:m.session_version},sessionSecret,{subject:m.id,audience:'rbx-box-members',issuer:'rbx-box-server',expiresIn:'7d',algorithm:'HS256'}),cookieOptions)}
 const auth=route(async(req,res,next)=>{
  const cookie=String(req.headers.cookie||'').split(';').map(p=>p.trim()).find(p=>p.startsWith(COOKIE+'='));let data;
  try{data=jwt.verify(decodeURIComponent(cookie?.slice(COOKIE.length+1)||''),sessionSecret,{algorithms:['HS256'],audience:'rbx-box-members',issuer:'rbx-box-server'})}catch{throw fail(401,'Entre na sua conta da BOX.')}
  const m=(await db.query('SELECT * FROM box_members WHERE id=$1',[data.sub])).rows[0];
  if(!m||m.blocked||data.type!=='box_member'||data.ver!==m.session_version)throw fail(401,'Entre novamente na sua conta da BOX.');req.member=m;next();
 });
 // Browser writes must originate from this same service. No wildcard CORS.
 app.use('/api/members',(req,res,next)=>{if(req.path!=='/payment-webhook'&&req.method==='POST'&&req.headers.origin){let origin;try{origin=new URL(req.headers.origin)}catch{return res.status(403).json({error:'Origem inválida.'})}if(origin.host!==req.get('host'))return res.status(403).json({error:'Abra a área de membros no endereço oficial da BOX.'})}next()});
 const encrypt=raw=>{if(!encryptionKey)throw fail(503,'A liberação das keys está em configuração. Sua compra foi preservada.');const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',encryptionKey,iv);const value=Buffer.concat([cipher.update(raw,'utf8'),cipher.final()]);return [iv,cipher.getAuthTag(),value].map(b=>b.toString('hex')).join('.')};
 const decrypt=value=>{if(!encryptionKey)throw fail(503,'A liberação das keys está em configuração.');try{const [iv,tag,data]=value.split('.').map(x=>Buffer.from(x,'hex'));const c=crypto.createDecipheriv('aes-256-gcm',encryptionKey,iv);c.setAuthTag(tag);return Buffer.concat([c.update(data),c.final()]).toString('utf8')}catch{throw fail(503,'Não foi possível recuperar a key. Fale com o suporte, sem gerar outra compra.')}};
 async function ownOrder(id,member){if(!uuid(id))throw fail(404,'Pedido não encontrado.');const row=(await db.query('SELECT * FROM box_orders WHERE id=$1 AND member_id=$2',[id,member.id])).rows[0];if(!row)throw fail(404,'Pedido não encontrado.');return row}
 async function sync(order){
  if(order.source==='manual')return order;
  if(!order.payment_id)return order;
  const status=validatePayment(await payments.get(order.payment_id),order);
  await db.query('UPDATE box_orders SET status=$1,checked_at=$2 WHERE id=$3',[status,new Date(),order.id]);order.status=status;
  if(['refunded','charged_back','cancelled'].includes(status)){
   const l=(await db.query('SELECT key_id FROM box_member_licenses WHERE order_id=$1',[order.id])).rows[0];if(l)await db.query("UPDATE box_keys SET status='revoked' WHERE id=$1",[l.key_id]);
  }return order;
 }
 async function orderView(order){
  const l=(await db.query('SELECT l.key_cipher,k.id,k.key_suffix,k.status,k.hwid,k.expires_at FROM box_member_licenses l JOIN box_keys k ON k.id=l.key_id WHERE l.order_id=$1',[order.id])).rows[0];
  return{id:order.id,createdAt:order.created_at,status:order.status,amountCents:Number(order.amount_cents),source:order.source,qrCode:order.status==='pending'?order.qr_code:null,qrImage:order.status==='pending'?order.qr_image:null,license:l?{key:decrypt(l.key_cipher),status:l.status,activated:!!l.hwid,expiresAt:l.expires_at}:null};
 }
 app.post('/api/members/payment-webhook',route(async(req,res)=>{
  if(!config.webhookSecret)throw fail(503,'Notificações de pagamento não configuradas.');
  const id=req.query['data.id'],requestId=req.get('x-request-id'),signature=req.get('x-signature')||'';
  if(typeof id!=='string'||!/^\d{1,30}$/.test(id)||!/^[-a-zA-Z0-9]{5,128}$/.test(requestId||''))throw fail(401,'Notificação inválida.');
  const parts=Object.fromEntries(signature.split(',').map(part=>part.trim().split('=')));
  if(!/^\d{10,13}$/.test(parts.ts||'')||!/^[a-f0-9]{64}$/.test(parts.v1||''))throw fail(401,'Notificação inválida.');
  const stamp=Number(parts.ts)*(parts.ts.length<=10?1000:1);
  if(Math.abs(Date.now()-stamp)>300000)throw fail(401,'Notificação expirada.');
  const expected=crypto.createHmac('sha256',config.webhookSecret).update('id:'+id+';request-id:'+requestId+';ts:'+parts.ts+';').digest();
  if(!crypto.timingSafeEqual(expected,Buffer.from(parts.v1,'hex')))throw fail(401,'Assinatura inválida.');
  const order=(await db.query('SELECT * FROM box_orders WHERE payment_id=$1',[id])).rows[0];
  if(!order)return res.status(202).json({ok:true});await sync(order);res.json({ok:true});
 }));
 app.get('/api/members/config',(_req,res)=>{let downloadUrl=null;try{const u=new URL(config.downloadUrl);if(u.protocol==='https:'&&!u.username&&!u.password)downloadUrl=u.href}catch{}res.json({priceCents:PRICE,originalPriceCents:9990,product:'RBX BOX',pixAvailable:!!config.mpToken&&!!encryptionKey,downloadUrl})});
 app.post('/api/members/register',authLimit,route(async(req,res)=>{
  const email=String(req.body?.email||'').trim().toLowerCase(),name=String(req.body?.name||'').trim(),password=req.body?.password;
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254||name.length<2||name.length>100||!validPassword(password))throw fail(400,'Informe seu nome, e-mail e uma senha entre 10 e 128 caracteres.');
  const m={id:crypto.randomUUID(),email,name,password_hash:await passwordHash(password)};
  try{await db.query('INSERT INTO box_members(id,email,name,password_hash) VALUES($1,$2,$3,$4)',[m.id,email,name,m.password_hash])}catch(e){if(e.code==='23505')throw fail(409,'Já existe uma conta com esse e-mail. Use Entrar.');throw e}
  m.session_version=0;login(res,m);res.status(201).json({member:cleanMember(m)});
 }));
 app.post('/api/members/login',authLimit,route(async(req,res)=>{
  const email=String(req.body?.email||'').trim().toLowerCase(),password=String(req.body?.password||'');if(password.length>128)throw fail(401,'E-mail ou senha inválidos.');
  const m=(await db.query('SELECT * FROM box_members WHERE email=$1',[email])).rows[0];
  // Dummy scrypt keeps unknown-account attempts comparable to wrong-password attempts.
  const stored=m?.password_hash||'00000000000000000000000000000000:'+('00'.repeat(64));const valid=await passwordMatches(password,stored);
  if(!m||!valid||m.blocked)throw fail(401,'E-mail ou senha inválidos.');login(res,m);res.json({member:cleanMember(m)});
 }));
 app.post('/api/members/logout',auth,route(async(req,res)=>{await db.query('UPDATE box_members SET session_version=session_version+1 WHERE id=$1',[req.member.id]);res.clearCookie(COOKIE,{...cookieOptions,maxAge:undefined});res.json({ok:true})}));
 app.post('/api/members/recover',authLimit,route(async(req,res)=>{
  const token=String(req.body?.token||'');if(!/^[a-f0-9]{48}$/.test(token)||!validPassword(req.body?.password))throw fail(400,'Use o link recebido do suporte e uma senha de no mínimo 10 caracteres.');
  const r=await db.query('UPDATE box_members SET password_hash=$1,session_version=session_version+1,recovery_hash=NULL,recovery_expires=NULL WHERE recovery_hash=$2 AND recovery_expires>$3 RETURNING id',[await passwordHash(req.body.password),hash(token),new Date()]);if(!r.rowCount)throw fail(400,'Link inválido ou expirado. Peça outro ao suporte.');res.json({ok:true});
 }));
 app.get('/api/members/me',auth,(req,res)=>res.json({member:cleanMember(req.member)}));
 app.get('/api/members/orders',auth,route(async(req,res)=>{
  const rows=(await db.query('SELECT * FROM box_orders WHERE member_id=$1 ORDER BY created_at DESC LIMIT 50',[req.member.id])).rows;
  for(const row of rows.slice(0,5))if(row.payment_id&&(!row.checked_at||Date.now()-new Date(row.checked_at)>(['pending','in_process'].includes(row.status)?10000:60000)))try{await sync(row)}catch{/* Do not erase or approve an order on a network error. */}
  res.json({orders:await Promise.all(rows.map(orderView))});
 }));
 app.post('/api/members/orders',auth,purchaseLimit,route(async(req,res)=>{
  if(!config.mpToken||!encryptionKey)throw fail(503,'O Pix está em configuração. Para uma compra já feita, fale com o suporte para liberar seu acesso.');
  const attempt=String(req.body?.attempt||'');if(!uuid(attempt))throw fail(400,'Atualize a página e tente novamente.');
  const id=crypto.randomUUID();await db.query('INSERT INTO box_orders(id,member_id,attempt,amount_cents) VALUES($1,$2,$3,$4) ON CONFLICT(member_id,attempt) DO NOTHING',[id,req.member.id,attempt,PRICE]);
  let order=(await db.query('SELECT * FROM box_orders WHERE member_id=$1 AND attempt=$2',[req.member.id,attempt])).rows[0];
  if(!order.payment_id){
   const p=await payments.create({order,member:req.member});if(!p.id)throw fail(502,'O Pix não retornou um identificador. Tente novamente.');
   order.payment_id=String(p.id);validatePayment(p,order);const qr=p.point_of_interaction?.transaction_data;
   if(p.status!=='approved'&&(!qr?.qr_code||!qr?.qr_code_base64))throw fail(502,'O QR Code ainda não está disponível. Tente novamente.');
   await db.query('UPDATE box_orders SET payment_id=$1,qr_code=$2,qr_image=$3 WHERE id=$4',[String(p.id),qr?.qr_code||null,qr?.qr_code_base64||null,order.id]);order=await ownOrder(order.id,req.member);
  }
  order=await sync(order);res.json({order:await orderView(order)});
 }));
 app.get('/api/members/orders/:id',auth,statusLimit,route(async(req,res)=>{const order=await sync(await ownOrder(req.params.id,req.member));res.json({order:await orderView(order)})}));
 app.post('/api/members/orders/:id/license',auth,purchaseLimit,route(async(req,res)=>{
  const order=await sync(await ownOrder(req.params.id,req.member));if(order.status!=='approved')throw fail(409,'A key só pode ser gerada após o pagamento aprovado.');if(!encryptionKey)throw fail(503,'A liberação das keys está em configuração.');
  const existing=(await db.query('SELECT order_id FROM box_member_licenses WHERE order_id=$1',[order.id])).rows[0];if(existing)return res.json({order:await orderView(order)});
  // A deterministic secret HMAC per immutable purchase + DB uniqueness makes concurrent
  // clicks and crash retries converge on the same key; no new key on every visit.
  const raw='BOX-'+crypto.createHmac('sha256',encryptionKey).update('purchase-key-v1:'+order.id+':'+req.member.id).digest('hex').slice(0,24).toUpperCase().match(/.{8}/g).join('-');
  const cipher=encrypt(raw);const r=await db.query(`INSERT INTO box_keys(key_hash,key_suffix,duration_days) VALUES($1,$2,0) ON CONFLICT(key_hash) DO UPDATE SET key_hash=EXCLUDED.key_hash RETURNING id`,[hash(raw),raw.slice(-8)]);
  await db.query('INSERT INTO box_member_licenses(order_id,member_id,key_id,key_cipher) VALUES($1,$2,$3,$4) ON CONFLICT(order_id) DO NOTHING',[order.id,req.member.id,r.rows[0].id,cipher]);
  res.json({order:await orderView(order)});
 }));
 app.get('/api/admin/box/members',adminAuth,route(async(_req,res)=>{
  const rows=(await db.query('SELECT id,email,name,created_at FROM box_members ORDER BY created_at DESC LIMIT 500')).rows;
  const result=[];for(const m of rows){const orders=(await db.query('SELECT id,status,source,amount_cents,created_at FROM box_orders WHERE member_id=$1 ORDER BY created_at DESC',[m.id])).rows;result.push({...m,orders})}res.json({members:result});
 }));
 app.post('/api/admin/box/members/manual',adminAuth,route(async(req,res)=>{
  const email=String(req.body?.email||'').trim().toLowerCase();const member=(await db.query('SELECT * FROM box_members WHERE email=$1',[email])).rows[0];if(!member)throw fail(404,'Peça ao cliente para criar a conta da BOX com esse e-mail primeiro.');
  const reference=String(req.body?.reference||'').trim();if(reference.length<4||reference.length>100)throw fail(400,'Informe a referência única da compra conferida.');
  const attempt='manual:'+hash(reference);const existing=(await db.query('SELECT * FROM box_orders WHERE member_id=$1 AND attempt=$2',[member.id,attempt])).rows[0];
  if(existing)return res.json({ok:true,orderId:existing.id});const id=crypto.randomUUID();
  await db.query(`INSERT INTO box_orders(id,member_id,attempt,amount_cents,source,status,approved_by) VALUES($1,$2,$3,$4,'manual','approved',$5) ON CONFLICT(member_id,attempt) DO NOTHING`,[id,member.id,attempt,PRICE,req.admin.sub]);
  const saved=(await db.query('SELECT id FROM box_orders WHERE member_id=$1 AND attempt=$2',[member.id,attempt])).rows[0];res.json({ok:true,orderId:saved.id});
 }));
 app.get('/api/admin/box/members/orders/:id/license',adminAuth,route(async(req,res)=>{
  const l=(await db.query('SELECT key_cipher FROM box_member_licenses WHERE order_id=$1',[req.params.id])).rows[0];if(!l)throw fail(404,'O cliente ainda não gerou a key.');res.json({key:decrypt(l.key_cipher)});
 }));
 app.post('/api/admin/box/members/:id/recovery',adminAuth,route(async(req,res)=>{
  const token=crypto.randomBytes(24).toString('hex'),r=await db.query('UPDATE box_members SET recovery_hash=$1,recovery_expires=$2 WHERE id=$3 RETURNING id',[hash(token),new Date(Date.now()+30*60000),req.params.id]);if(!r.rowCount)throw fail(404,'Conta não encontrada.');res.json({path:'/membros.html?recuperar='+token});
 }));
 app.use(['/api/members','/api/admin/box/members'],(err,req,res,next)=>{if(!err.status)console.error('BOX Members:',err.message);res.status(err.status||500).json({error:err.status?err.message:'Não foi possível concluir. Tente novamente.'})});
}

